from hbonboard.models import KycRequest
from hbonboard.util.dates import compact
from hbonboard.util.text import vendor_name


def to_request(member):
    return KycRequest(
        ref=member.member_id,
        name=vendor_name(member.name),
        birth=compact(member.birth),
        phone=member.phone,
    )


def build_batch(members):
    """One line per member, in phone-number order (the vendor's matching key)."""
    seen, requests = set(), []
    for member in members:
        if member.member_id in seen:
            continue
        seen.add(member.member_id)
        requests.append(to_request(member))
    return sorted(requests, key=lambda r: r.phone)
"""Vendor verdict codes -> member status."""
from hbonboard.models import ACTIVE, KYC_DONE, REJECTED, REVIEW

# 1 = identity matched, 2 = identity did not match; anything else goes to a person
VERDICT_STATUS = {1: ACTIVE, 2: REJECTED}


def status_for(code):
    return VERDICT_STATUS.get(code, REVIEW)


def apply_verdict(member, code):
    member.verdict = code
    member.status = status_for(code)
    member.kyc_state = KYC_DONE
    member.history.append(member.status)
    return member
"""Identity-check run: sends new members to the vendor and applies verdicts."""
from hbonboard.kyc.requests import build_batch
from hbonboard.kyc.verdicts import apply_verdict
from hbonboard.models import KYC_NEW, KYC_SENT


class VerificationService:
    def __init__(self, repo, client, settings, notifier=None, on_resolved=None):
        self.repo = repo
        self.client = client
        self.settings = settings
        self.notifier = notifier
        self.on_resolved = on_resolved

    def _send_new(self):
        fresh = sorted(self.repo.by_kyc_state(KYC_NEW), key=lambda m: m.member_id)
        if not fresh:
            return [], 0
        ticket = self.client.submit(build_batch(fresh))
        for member in fresh:
            member.kyc_state = KYC_SENT
            member.kyc_job = ticket.job_id
            member.history.append(KYC_SENT)
        return [ticket.job_id], len(fresh)

    def _collect(self):
        resolved, waiting = [], []
        for member in sorted(self.repo.by_kyc_state(KYC_SENT), key=lambda m: m.member_id):
            code = self.client.result(member.member_id)
            if code is None:
                # the vendor has not answered for this one yet; ask again next run
                waiting.append(member.member_id)
                continue
            apply_verdict(member, code)
            if self.notifier:
                self.notifier.verdict(member)
            resolved.append({"id": member.member_id, "status": member.status})
        return resolved, waiting

    def run(self):
        jobs, sent = self._send_new()
        resolved, waiting = self._collect()
        if resolved and self.on_resolved:
            self.on_resolved()
        return {"jobs": jobs, "sent": sent, "resolved": resolved, "waiting": len(waiting)}
"""Admin console: where every member stands in the onboarding funnel."""
from hbonboard.models import ACTIVE, PENDING, REJECTED, REVIEW
from hbonboard.util.phone import mask_phone


class BacklogReport:
    def __init__(self, repo, settings, cache):
        self.repo = repo
        self.settings = settings
        self.cache = cache

    def invalidate(self):
        self.cache.invalidate("backlog")

    def summary(self):
        cached = self.cache.get("backlog")
        if cached is not None:
            return cached
        members = sorted(self.repo.all(), key=lambda m: m.member_id)
        counts = {s: 0 for s in (PENDING, ACTIVE, REJECTED, REVIEW)}
        by_channel = {}
        for member in members:
            counts[member.status] = counts.get(member.status, 0) + 1
            if member.status == PENDING:
                by_channel[member.channel] = by_channel.get(member.channel, 0) + 1
        pending = [
            {
                "id": m.member_id,
                "phone": mask_phone(m.phone),
                "channel": m.channel,
                "kyc_state": m.kyc_state,
                "job": m.kyc_job,
            }
            for m in members if m.status == PENDING
        ]
        report = {
            "total": len(members),
            "counts": counts,
            "pending_by_channel": dict(sorted(by_channel.items())),
            "pending": pending[: self.settings.pending_preview],
        }
        self.cache.put("backlog", report)
        return report
